import { createListState } from "./components/list-select.js";
import { getEnvironmentConfig } from "../../src/config/index.js";
import { cwd } from "../../src/platform/index.js";
import { join } from "../../src/platform/compat/path/index.js";
export function createInitialState() {
    return {
        view: "dashboard",
        previousView: null,
        server: {
            running: false,
            url: "http://localhost:8080",
            port: 8080,
            errors: 0,
            warnings: 0,
        },
        mcp: {
            enabled: false,
            transport: null,
            connected: false,
        },
        remote: { user: null },
        projects: createListState([]),
        remoteProjects: createListState([]),
        templates: createListState([]),
        activeList: "projects",
        input: {
            active: false,
            prompt: "",
            value: "",
            cursorPos: 0,
            purpose: null,
        },
        logs: [],
        maxLogs: 100,
        logsExpanded: false,
        logScroll: 0,
        authProviderIndex: 0,
        newProjectIndex: 0,
        showHelp: false,
    };
}
export function setProjects(projects) {
    return (state) => ({
        ...state,
        projects: createListState(projects.map((p) => ({
            id: p.slug,
            label: p.slug,
            meta: shortenPath(p.path),
            data: { slug: p.slug, path: p.path, type: "local" },
        }))),
    });
}
/**
 * Remote projects are the same concept as local ones and navigate through the
 * same list module. A remote project's path is where a pull would put it,
 * under `baseDir/projects/` (the working directory by default).
 */
export function setRemoteProjects(projects, baseDir = cwd()) {
    return (state) => withSelectableActiveList({
        ...state,
        remoteProjects: createListState(projects.map((p) => ({
            id: p.slug,
            label: p.slug,
            data: { slug: p.slug, path: remoteProjectPath(p.slug, baseDir), type: "remote" },
        }))),
    });
}
/** Where `pull` places a remote project, and what the IDE opens. */
export function remoteProjectPath(slug, baseDir = cwd()) {
    return join(baseDir, "projects", slug);
}
export function setTemplates(templates) {
    return (state) => ({
        ...state,
        templates: createListState(templates.map((t) => ({
            id: t.id,
            label: t.name,
            description: t.description,
            data: { slug: t.id, path: "", type: "template" },
        }))),
    });
}
export function updateServer(update) {
    return (state) => ({ ...state, server: { ...state.server, ...update } });
}
export function updateMCP(update) {
    return (state) => ({ ...state, mcp: { ...state.mcp, ...update } });
}
/**
 * The dashboard renders the remote section only for a signed-in user with at
 * least one project. Pointing `activeList` at a section that is not rendered
 * shows no cursor anywhere and resolves action keys to no project, so keep the
 * two in step whenever either input changes.
 */
function withSelectableActiveList(state) {
    if (state.activeList !== "remoteProjects")
        return state;
    const selectable = !!state.remote.user && state.remoteProjects.items.length > 0;
    return selectable ? state : { ...state, activeList: "projects" };
}
export function setRemoteUser(user) {
    return (state) => withSelectableActiveList({ ...state, remote: { ...state.remote, user } });
}
export function navigateTo(view) {
    return (state) => ({ ...state, view, previousView: state.view });
}
export function goBack() {
    return (state) => ({
        ...state,
        view: state.previousView ?? "dashboard",
        previousView: null,
    });
}
export function setActiveList(list) {
    return (state) => ({ ...state, activeList: list });
}
export function updateActiveList(updater) {
    return (state) => ({ ...state, [state.activeList]: updater(state[state.activeList]) });
}
export function startInput(prompt, purpose, initialValue) {
    return (state) => ({
        ...state,
        input: {
            active: true,
            prompt,
            value: initialValue ?? "",
            cursorPos: initialValue?.length ?? 0,
            purpose,
        },
    });
}
export function updateInputValue(value, cursorPos) {
    return (state) => ({
        ...state,
        input: { ...state.input, value, cursorPos },
    });
}
export function endInput() {
    return (state) => ({
        ...state,
        input: {
            active: false,
            prompt: "",
            value: "",
            cursorPos: 0,
            purpose: null,
        },
    });
}
export function addLog(level, message, meta) {
    return (state) => {
        const logs = [...state.logs, { time: new Date(), level, message, meta }];
        if (logs.length > state.maxLogs)
            logs.shift();
        return { ...state, logs };
    };
}
export function toggleLogsExpanded() {
    return (state) => ({
        ...state,
        logsExpanded: !state.logsExpanded,
        logScroll: 0,
    });
}
export function toggleHelp() {
    return (state) => ({ ...state, showHelp: !state.showHelp });
}
export function scrollLogs(direction) {
    return (state) => {
        if (!state.logsExpanded)
            return state;
        const maxScroll = Math.max(0, state.logs.length - 5);
        const delta = direction === "up" ? 1 : -1;
        const newScroll = Math.min(maxScroll, Math.max(0, state.logScroll + delta));
        return { ...state, logScroll: newScroll };
    };
}
function shortenPath(path, env = getEnvironmentConfig()) {
    // Prefer relative path to cwd
    const currentDir = cwd();
    const cwdPrefix = `${currentDir}/`;
    if (path === currentDir)
        return "./";
    if (path.startsWith(cwdPrefix))
        return `./${path.slice(cwdPrefix.length)}`;
    // Fall back to ~ for home
    const home = env.homeDir ?? "";
    if (home && path.startsWith(home))
        return `~${path.slice(home.length)}`;
    return path;
}
export function getActiveList(state) {
    return state[state.activeList];
}
export function getActiveSelection(state) {
    const list = getActiveList(state);
    return list.items[list.selectedIndex];
}
